/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  const subTab = api.state.subscriptionsTabId;
  const tab = (subTab == "p1c1")? "p1" : "p2";
  return [[tab,subTab]];
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  // Display instance container when either Instance Entitlement module is clicked or if All entitleent module is clicked
  return api.state.subscriptionsTabId !== 'p1' && api.state.subscriptionsTabId !== 'p1c1';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  // p2 is the id of Account level entitlement module. Display cloud entitlement tab if user clicks on Account level entitlement and if cloud entitlement is displayed
  if (api.state.subscriptionsTabId === 'p2' || api.state.subscriptionsTabId === 'p2c1')
    return !api.state.shouldShowCloudEntitlementTab;

  // p2c1 is the id of Cloud Entitlement tab. Hide this container when any other tab is selected
  return api.state.subscriptionsTabId != 'p2c1';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  // p2 is the id of Account level entitlement module. If user clicks on Account level entitlement, hide creator tab if
  // creator tab shouldn't be displayed or cloud or assist tab is displayed
  if (api.state.subscriptionsTabId === 'p2')
    return api.state.shouldShowCloudEntitlementTab || api.state.shouldShowAssistUsageTab || !api.state.shouldShowAssistCreatorTab;

  //p2c3 is the id of Creator Subscriptions tab. Hide this container when any other tab is selected
  return api.state.subscriptionsTabId != 'p2c3';
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    /**
     * Syncing params value with the home tab index
     */
    const homeTabs = {
        'overview': 0,
        'subscriptions': 1,
        'issues': 2,
        'insights': 3,
        'settings': 4
    };
    const selectedTabIndex = (api.context.props.sm == '') ? 0 : homeTabs[api.context.props.sm];
    return selectedTabIndex;
}
